command: cd /Users/gabe/Projects/agent-plugins
python3 - <<'PYEOF'
import re, glob

files = sorted(glob.glob("plugins/*/agents/*.md"))
blocks = {}
for f in files:
    content = open(f, encoding="utf-8").read()
    m = re.search(r"<constitution>(.*?)</constitution>", content, re.S)
    blocks[f] = m.group(1) if m else None

by_text = {}
for f, b in blocks.items():
    if b is None: continue
    by_text.setdefault(b, []).append(f)

print(f"Total agent files: {len(files)}")
print(f"Missing <constitution>: {[f for f,b in blocks.items() if b is None]}")
print(f"Distinct constitution variants: {len(by_text)} (should be 1)")

order_issues = []
for f in files:
    content = open(f, encoding="utf-8").read()
    tags = re.findall(r"^<(constitution|load_first|backstory|goal|judgment|output|role|success_criteria)>", content, re.M)
    core_only = [t for t in tags if t != "load_first"]
    if core_only != ["constitution","backstory","goal","judgment","output"]:
        order_issues.append((f, tags))
    if "role" in tags or "success_criteria" in tags:
        order_issues.append((f, "LEGACY: " + str(tags)))
    if "load_first" in tags and tags.index("load_first") != 1:
        order_issues.append((f, "load_first misplaced: " + str(tags)))
print(f"Section-order/legacy issues: {len(order_issues)}")
for f,t in order_issues: print(f"  {f}: {t}")

ears_kw = re.compile(r'\bSHALL\b', re.M)
ears_issues = []
for f in files:
    content = open(f, encoding="utf-8").read()
    for tag in ["backstory","goal","judgment","load_first"]:
        m = re.search(rf"<{tag}>(.*?)</{tag}>", content, re.S)
        if m and ears_kw.search(m.group(1)):
            ears_issues.append((f, tag))
print(f"EARS (SHALL) outside constitution/output: {len(ears_issues)}")
for f,t in ears_issues: print(f"  {f} [{t}]")
PYEOF
[/external_agent_tool_call]

